CREATE TABLE public.saved_plans(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,plan_id uuid NOT NULL REFERENCES public.plans(id) ON DELETE CASCADE,PRIMARY KEY(user_id,plan_id));
GRANT SELECT,INSERT,DELETE ON public.saved_plans TO authenticated; GRANT ALL ON public.saved_plans TO service_role; ALTER TABLE public.saved_plans ENABLE ROW LEVEL SECURITY; CREATE POLICY "own saved plans" ON public.saved_plans FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.friendships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requester uuid NOT NULL REFERENCES public.profiles(id),recipient uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','declined')),created_at timestamptz NOT NULL DEFAULT now(),CHECK(requester<>recipient));
CREATE UNIQUE INDEX friendships_pair ON public.friendships(least(requester,recipient),greatest(requester,recipient));
GRANT SELECT,INSERT ON public.friendships TO authenticated; GRANT ALL ON public.friendships TO service_role; ALTER TABLE public.friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY "friends see own connections" ON public.friendships FOR SELECT TO authenticated USING((requester=auth.uid() OR recipient=auth.uid()) AND NOT public.people_blocked(requester,recipient));
CREATE POLICY "request own friendship" ON public.friendships FOR INSERT TO authenticated WITH CHECK(requester=auth.uid() AND status='pending' AND NOT public.people_blocked(requester,recipient));
CREATE FUNCTION public.are_friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.friendships WHERE status='accepted' AND ((requester=a AND recipient=b) OR (recipient=a AND requester=b))) AND NOT public.people_blocked(a,b) $$;
REVOKE ALL ON FUNCTION public.are_friends(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.are_friends(uuid,uuid) TO authenticated,service_role;
CREATE FUNCTION public.respond_friend(_id uuid,_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.friendships SET status=CASE WHEN _accept THEN 'accepted' ELSE 'declined' END WHERE id=_id AND recipient=auth.uid() AND status='pending' AND NOT public.people_blocked(requester,recipient); IF NOT FOUND THEN RAISE EXCEPTION 'Friend request unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.respond_friend(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_friend(uuid,boolean) TO authenticated;
CREATE TABLE public.friend_codes(user_id uuid PRIMARY KEY REFERENCES public.profiles(id),code uuid NOT NULL UNIQUE DEFAULT gen_random_uuid()); GRANT SELECT,INSERT ON public.friend_codes TO authenticated; GRANT ALL ON public.friend_codes TO service_role; ALTER TABLE public.friend_codes ENABLE ROW LEVEL SECURITY; CREATE POLICY "own friend code" ON public.friend_codes FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.redeem_friend_code(_code uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE person uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT user_id INTO person FROM public.friend_codes WHERE code=_code; IF person IS NULL OR person=auth.uid() OR public.people_blocked(person,auth.uid()) THEN RAISE EXCEPTION 'This invite code is unavailable'; END IF; INSERT INTO public.friendships(requester,recipient) VALUES(auth.uid(),person) ON CONFLICT DO NOTHING; END $$; REVOKE ALL ON FUNCTION public.redeem_friend_code(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.redeem_friend_code(uuid) TO authenticated;
CREATE TABLE public.plan_invites(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES public.plans(id) ON DELETE CASCADE,inviter uuid NOT NULL REFERENCES public.profiles(id),invitee uuid NOT NULL REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'invited' CHECK(status IN('invited','going','maybe','declined')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(plan_id,invitee),CHECK(inviter<>invitee));
GRANT SELECT,INSERT ON public.plan_invites TO authenticated; GRANT ALL ON public.plan_invites TO service_role; ALTER TABLE public.plan_invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY "private invites" ON public.plan_invites FOR SELECT TO authenticated USING((inviter=auth.uid() OR invitee=auth.uid() OR public.is_plan_member(plan_id,auth.uid())) AND NOT public.people_blocked(inviter,invitee));
CREATE POLICY "attendees invite friends" ON public.plan_invites FOR INSERT TO authenticated WITH CHECK(inviter=auth.uid() AND status='invited' AND public.is_plan_member(plan_id,auth.uid()) AND public.are_friends(inviter,invitee));
CREATE FUNCTION public.respond_invite(_id uuid,_status text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.plan_invites; r text; BEGIN SELECT * INTO i FROM public.plan_invites WHERE id=_id AND invitee=auth.uid() FOR UPDATE; IF i.id IS NULL OR public.people_blocked(i.inviter,i.invitee) OR _status NOT IN('going','maybe','declined') THEN RAISE EXCEPTION 'Invite unavailable'; END IF; IF _status='going' THEN INSERT INTO public.join_requests(plan_id,user_id) VALUES(i.plan_id,auth.uid()) ON CONFLICT(plan_id,user_id) DO NOTHING; SELECT status INTO r FROM public.join_requests WHERE plan_id=i.plan_id AND user_id=auth.uid(); END IF; UPDATE public.plan_invites SET status=_status WHERE id=i.id; RETURN COALESCE(r,_status); END $$; REVOKE ALL ON FUNCTION public.respond_invite(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_invite(uuid,text) TO authenticated;
CREATE FUNCTION public.friends_going(_plan uuid DEFAULT NULL) RETURNS TABLE(plan_id uuid,person_id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT j.plan_id,p.id,split_part(p.name,' ',1) FROM public.join_requests j JOIN public.profiles p ON p.id=j.user_id WHERE auth.uid() IS NOT NULL AND j.status='approved' AND public.are_friends(auth.uid(),j.user_id) AND (_plan IS NULL OR j.plan_id=_plan) $$; REVOKE ALL ON FUNCTION public.friends_going(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.friends_going(uuid) TO authenticated;